import json, sys
R = '/workspace/case/campaigns/c1/runs/'
meta = {}
for l in open('/workspace/case/dataset/train.meta.jsonl'):
    m = json.loads(l); meta[m['id']] = m


def load(name):
    d = json.load(open(R + name + '.json'))
    out = {}
    for e in d['examples']:
        eid = e['example_id']
        ref = json.loads(e['reference'])
        rel = {ref['primary']} | set(ref.get('acceptable', []))
        # ответ решателя из calls
        out[eid] = rel
    ans = {}
    for c in d['calls']:
        if c['name'] == 'solver':
            try:
                ans[c['attributes']['example_id']] = json.loads(c['outputs'])
            except Exception:
                ans[c['attributes']['example_id']] = []
    return out, ans, d['metrics']['score']


def sc(rel, a):
    a = a[:3]
    acc = 1.0 if a and a[0] in rel else 0.0
    np3 = len(set(a) & rel) / min(3, len(rel))
    return 0.7 * acc + 0.3 * np3, acc


names = sys.argv[1:]
data = {n: load(n) for n in names}
base = data[names[0]]
ids = list(base[0])
for n in names:
    rel, ans, score = data[n]
    per = {i: sc(rel[i], ans[i]) for i in ids}
    print(n, 'score', score, 'recomputed', round(sum(p[0] for p in per.values()) / len(ids), 5), 'acc1', round(sum(p[1] for p in per.values()) / len(ids), 4))
for n in names[1:]:
    a0, a1 = base[1], data[n][1]
    r0 = {i: sc(base[0][i], a0[i])[0] for i in ids}
    r1 = {i: sc(base[0][i], a1[i])[0] for i in ids}
    top1 = sum(1 for i in ids if a0[i][:1] == a1[i][:1])
    same = sum(1 for i in ids if a0[i][:3] == a1[i][:3])
    better = sum(1 for i in ids if r1[i] > r0[i] + 1e-9); worse = sum(1 for i in ids if r1[i] < r0[i] - 1e-9)
    print(names[0], 'vs', n, 'top1 same', top1, 'top3 same', same, 'paired better/worse', better, worse)
    sty = {}
    for i in ids:
        s = meta[i]['style']; sty.setdefault(s, []).append((r0[i], r1[i]))
    print({s: (len(v), round(sum(x for x, _ in v) / len(v), 3), round(sum(y for _, y in v) / len(v), 3)) for s, v in sorted(sty.items())})

